	__models__GongNoteShape__00000001_.Body = `02. SID & STAR Procedures Story

[models.StandardInstrumentDepartureTimeSliceType] (SID) and [models.StandardInstrumentArrivalTimeSliceType] (STAR) connect runway directions
to en-route transitions via ordered [models.ProcedureTransitionType] branches, [models.ProcedureTransitionLegType], and [models.ProcedureAvailabilityType].
`
	__models__GongNoteShape__00000001_.BodyHTML = `<p>02. SID &amp; STAR Procedures Story
<p><a href="/models#StandardInstrumentDepartureTimeSliceType">models.StandardInstrumentDepartureTimeSliceType</a> (SID) and <a href="/models#StandardInstrumentArrivalTimeSliceType">models.StandardInstrumentArrivalTimeSliceType</a> (STAR) connect runway directions
to en-route transitions via ordered <a href="/models#ProcedureTransitionType">models.ProcedureTransitionType</a> branches, <a href="/models#ProcedureTransitionLegType">models.ProcedureTransitionLegType</a>, and <a href="/models#ProcedureAvailabilityType">models.ProcedureAvailabilityType</a>.
`
	__models__GongNoteShape__00000001_.X = 40.000000
	__models__GongNoteShape__00000001_.Y = 20.000000
	__models__GongNoteShape__00000001_.Width = 640.000000
	__models__GongNoteShape__00000001_.Height = 124.000000
	__models__GongNoteShape__00000001_.IsHidden = false
	__models__GongNoteShape__00000001_.Matched = false
	__models__GongNoteShape__00000001_.IsExpanded = false
	__models__GongNoteShape__00000002_.Name = `03. Instrument Approach Procedure (IAP)-Note03IAP`
	__models__GongNoteShape__00000002_.Identifier = `ref_models.Note03IAP`
	__models__GongNoteShape__00000002_.Body = `03. Instrument Approach Procedure (IAP) Story

An [models.InstrumentApproachProcedureTimeSliceType] defines precision or non-precision approach profiles ([models.FinalProfileType]),
SBAS/GBAS [models.FASDataBlockType], landing [models.ApproachConditionType] and [models.MinimaType] (OCA/H, DA/H), and [models.MissedApproachGroupType].
`
	__models__GongNoteShape__00000002_.BodyHTML = `<p>03. Instrument Approach Procedure (IAP) Story
<p>An <a href="/models#InstrumentApproachProcedureTimeSliceType">models.InstrumentApproachProcedureTimeSliceType</a> defines precision or non-precision approach profiles (<a href="/models#FinalProfileType">models.FinalProfileType</a>),
SBAS/GBAS <a href="/models#FASDataBlockType">models.FASDataBlockType</a>, landing <a href="/models#ApproachConditionType">models.ApproachConditionType</a> and <a href="/models#MinimaType">models.MinimaType</a> (OCA/H, DA/H), and <a href="/models#MissedApproachGroupType">models.MissedApproachGroupType</a>.
`
	__models__GongNoteShape__00000002_.X = 40.000000
	__models__GongNoteShape__00000002_.Y = 20.000000
	__models__GongNoteShape__00000002_.Width = 640.000000
	__models__GongNoteShape__00000002_.Height = 106.000000
	__models__GongNoteShape__00000002_.IsHidden = false
	__models__GongNoteShape__00000002_.Matched = false
	__models__GongNoteShape__00000002_.IsExpanded = false
	__models__GongNoteShape__00000003_.Name = `04. NavigationArea, TAA & CirclingArea-Note04NavigationArea`
	__models__GongNoteShape__00000003_.Identifier = `ref_models.Note04NavigationArea`
	__models__GongNoteShape__00000003_.Body = `04. NavigationArea, TAA & CirclingArea Story

[models.NavigationAreaTimeSliceType], [models.TerminalArrivalAreaTimeSliceType] (TAA), and [models.CirclingAreaTimeSliceType] define obstacle clearance
sectors ([models.NavigationAreaSectorType], [models.TerminalArrivalAreaSectorType]) and PANS-OPS [models.SectorDesignType] criteria.
`
	__models__GongNoteShape__00000003_.BodyHTML = `<p>04. NavigationArea, TAA &amp; CirclingArea Story
<p><a href="/models#NavigationAreaTimeSliceType">models.NavigationAreaTimeSliceType</a>, <a href="/models#TerminalArrivalAreaTimeSliceType">models.TerminalArrivalAreaTimeSliceType</a> (TAA), and <a href="/models#CirclingAreaTimeSliceType">models.CirclingAreaTimeSliceType</a> define obstacle clearance
sectors (<a href="/models#NavigationAreaSectorType">models.NavigationAreaSectorType</a>, <a href="/models#TerminalArrivalAreaSectorType">models.TerminalArrivalAreaSectorType</a>) and PANS-OPS <a href="/models#SectorDesignType">models.SectorDesignType</a> criteria.
`
	__models__GongNoteShape__00000003_.X = 40.000000
	__models__GongNoteShape__00000003_.Y = 20.000000
	__models__GongNoteShape__00000003_.Width = 640.000000
	__models__GongNoteShape__00000003_.Height = 124.000000
	__models__GongNoteShape__00000003_.IsHidden = false
	__models__GongNoteShape__00000003_.Matched = false
	__models__GongNoteShape__00000003_.IsExpanded = false
	__models__GongNoteShape__00000004_.Name = `05. Departure & Arrival Segment Legs-Note05DepartureArrivalLegs`
	__models__GongNoteShape__00000004_.Identifier = `ref_models.Note05DepartureArrivalLegs`
	__models__GongNoteShape__00000004_.Body = `05. Departure & Arrival Segment Legs Story

Individual ARINC 424 path-terminator legs for SIDs and STARs are modeled by [models.DepartureLegTimeSliceType], [models.ArrivalLegTimeSliceType],
and [models.ArrivalFeederLegTimeSliceType], connecting [models.TerminalSegmentPointType] fixes and [models.LandingTakeoffAreaCollectionType].
`
	__models__GongNoteShape__00000004_.BodyHTML = `<p>05. Departure &amp; Arrival Segment Legs Story
<p>Individual ARINC 424 path-terminator legs for SIDs and STARs are modeled by <a href="/models#DepartureLegTimeSliceType">models.DepartureLegTimeSliceType</a>, <a href="/models#ArrivalLegTimeSliceType">models.ArrivalLegTimeSliceType</a>,
and <a href="/models#ArrivalFeederLegTimeSliceType">models.ArrivalFeederLegTimeSliceType</a>, connecting <a href="/models#TerminalSegmentPointType">models.TerminalSegmentPointType</a> fixes and <a href="/models#LandingTakeoffAreaCollectionType">models.LandingTakeoffAreaCollectionType</a>.
`
	__models__GongNoteShape__00000004_.X = 40.000000
	__models__GongNoteShape__00000004_.Y = 20.000000
	__models__GongNoteShape__00000004_.Width = 640.000000
	__models__GongNoteShape__00000004_.Height = 124.000000
	__models__GongNoteShape__00000004_.IsHidden = false
	__models__GongNoteShape__00000004_.Matched = false
	__models__GongNoteShape__00000004_.IsExpanded = false
	__models__GongNoteShape__00000005_.Name = `06. Approach & Missed Approach Segment Legs-Note06ApproachLegs`
	__models__GongNoteShape__00000005_.Identifier = `ref_models.Note06ApproachLegs`
	__models__GongNoteShape__00000005_.Body = `06. Approach & Missed Approach Segment Legs Story

Approach transitions are decomposed into [models.InitialLegTimeSliceType] (IAF), [models.IntermediateLegTimeSliceType] (IF),
[models.FinalLegTimeSliceType] (FAF/FAP), and [models.MissedApproachLegTimeSliceType] (MAPt), referencing [models.TerminalSegmentPointType] and [models.HoldingUseType].
`
	__models__GongNoteShape__00000005_.BodyHTML = `<p>06. Approach &amp; Missed Approach Segment Legs Story
<p>Approach transitions are decomposed into <a href="/models#InitialLegTimeSliceType">models.InitialLegTimeSliceType</a> (IAF), <a href="/models#IntermediateLegTimeSliceType">models.IntermediateLegTimeSliceType</a> (IF),
<a href="/models#FinalLegTimeSliceType">models.FinalLegTimeSliceType</a> (FAF/FAP), and <a href="/models#MissedApproachLegTimeSliceType">models.MissedApproachLegTimeSliceType</a> (MAPt), referencing <a href="/models#TerminalSegmentPointType">models.TerminalSegmentPointType</a> and <a href="/models#HoldingUseType">models.HoldingUseType</a>.
`
	__models__GongNoteShape__00000005_.X = 40.000000
