	__models__GongNoteShape__00000006_.Name = `07. SafeAltitudeArea-Note07SafeAltitude`
	__models__GongNoteShape__00000006_.Identifier = `ref_models.Note07SafeAltitude`
	__models__GongNoteShape__00000006_.Body = `07. SafeAltitudeArea Story

[models.SafeAltitudeAreaTimeSliceType] models Minimum Sector Altitudes (MSA) or Emergency Safe Altitudes (ESA) around a reference navaid/waypoint,
partitioned into radial [models.SafeAltitudeAreaSectorType] pie slices with [models.CircleSectorType] geometry.
`
	__models__GongNoteShape__00000006_.BodyHTML = `<p>07. SafeAltitudeArea Story
<p><a href="/models#SafeAltitudeAreaTimeSliceType">models.SafeAltitudeAreaTimeSliceType</a> models Minimum Sector Altitudes (MSA) or Emergency Safe Altitudes (ESA) around a reference navaid/waypoint,
partitioned into radial <a href="/models#SafeAltitudeAreaSectorType">models.SafeAltitudeAreaSectorType</a> pie slices with <a href="/models#CircleSectorType">models.CircleSectorType</a> geometry.
`
