	__models__GongNoteShape__00000007_.Name = `08. HoldingPattern & UnplannedHolding-Note08HoldingPattern`
	__models__GongNoteShape__00000007_.Identifier = `ref_models.Note08HoldingPattern`
	__models__GongNoteShape__00000007_.Body = `08. HoldingPattern & UnplannedHolding Story

[models.HoldingPatternTimeSliceType] and [models.UnplannedHoldingTimeSliceType] specify racetrack holding fixes ([models.TerminalSegmentPointType]),
inbound course, turn direction, and leg length by distance ([models.HoldingPatternDistanceType]) or time ([models.HoldingPatternDurationType]).
`
	__models__GongNoteShape__00000007_.BodyHTML = `<p>08. HoldingPattern &amp; UnplannedHolding Story
<p><a href="/models#HoldingPatternTimeSliceType">models.HoldingPatternTimeSliceType</a> and <a href="/models#UnplannedHoldingTimeSliceType">models.UnplannedHoldingTimeSliceType</a> specify racetrack holding fixes (<a href="/models#TerminalSegmentPointType">models.TerminalSegmentPointType</a>),
inbound course, turn direction, and leg length by distance (<a href="/models#HoldingPatternDistanceType">models.HoldingPatternDistanceType</a>) or time (<a href="/models#HoldingPatternDurationType">models.HoldingPatternDurationType</a>).
`
	__models__GongNoteShape__00000007_.X = 40.000000
